// ===== CONFIG =====
const PREVIEW_CHARS = 1950;
const CHUNK_SIZE = 1990;

// ===== ORIGINAL JOB DATA =====
const job = $json.job ?? {};
const jobDesc = job.description ?? "";
const date_added = new Date();

// ===== BUILD NOTION CHUNKS =====
const chunks = [];
for (let i = 0; i < jobDesc.length; i += CHUNK_SIZE) {
  chunks.push({
    type: "text",
    text: {
      content: jobDesc.slice(i, i + CHUNK_SIZE)
    }
  });
}

// ===== PREVIEW =====
const isTruncated = jobDesc.length > PREVIEW_CHARS;
const preview = isTruncated
  ? jobDesc.slice(0, PREVIEW_CHARS) +
    "\n\n[TRUNCATED — full JD in page blocks]"
  : jobDesc;


// ===== BUILD EXTRACTOR LLM BODY =====
const systemPrompt = `You extract structured job requirements.

STRICT OUTPUT RULES:
- Output ONLY a single valid JSON object.
- No markdown, commentary, explanations.
- No duplicate items.
- Keep must_have to MAX 6 items.
- Keep nice_to_have to MAX 4 items.
- Do NOT include years of working experience inside must_have or nice_to_have.
- Experience years must go ONLY inside experience.min_years.
- role_cluster_hint must contain exactly one value.
- If multiple domains apply, select the dominant operational focus of the role.

SECTION PRIORITY RULE:
- When Duties, Responsibilities, Scope, or What You’ll Be Doing sections exist,
  must_have must primarily come from those sections.
- Operational responsibilities override qualifications/education.

REQUIREMENT QUALITY RULE:
- Each must_have must be a complete capability statement.
- Preserve tools, frameworks, regulatory references, and scope verbs.
- Only extract REQUIREMENTS that represent:
  - Concrete technical capability
  - Domain knowledge
  - Tool or framework usage
  - Security practice or methodology
  - Compliance or governance responsibility

- DO NOT extract generic soft skills such as:

  - communication skills
  - teamwork
  - stakeholder management
  - fast-paced environment
  - self-starter
  - passion for technology
  - detail oriented
  - problem solving ability
  - ability to multitask
  - ability to work independently

These are marketing language and MUST be ignored.

OPERATIONAL PRIORITIZATION RULE:
- Prioritize remediation, investigation, monitoring, implementation,
  configuration management, governance enforcement, assessment.

HARD CONSTRAINT RULE:
- Include ONLY explicit disqualifiers.
- Location restrictions
- Shift requirements
- Security clearance
- Citizenship/work authorization
- Explicit mandatory certifications
- If none exist → return []

CLUSTER RULES:
- Governance, risk, ISO, NIST → grc
- Vulnerability management, Qualys, Tenable → grc
- SIEM, monitoring, incident response, EDR → soc
- AWS/Azure/GCP security → cloud
- Pentest/red team → offensive
- Privacy/GDPR → privacy
- App security/secure coding → appsec
- If unclear → general

SENIORITY RULE:
- Leadership/ownership/strategy → senior
- Execution-focused 1–3 yrs → junior/mid
- If unclear → unknown

EXPERIENCE RULE:
- Extract min years ONLY if explicitly stated.
- Else min_years = null.

SCHEMA:
{
  "role_title": "string",
  "role_cluster_hint": "grc|soc|cloud|offensive|privacy|appsec|general",
  "experience": {
    "min_years": number|null,
    "seniority_level": "junior|mid|senior|lead|unknown"
  },
  "must_have": ["string"],
  "nice_to_have": ["string"],
  "hard_constraints": ["string"]
}`;


const userPrompt = `
Extract structured job requirements from the following job description:

${jobDesc}
`;

const ollamaBody = {
  model: "qwen2.5:7b",
  format: "json",
  options: {
    temperature: 0,
    num_ctx: 4096,
    num_predict: 500
  },
  stream: false,
  messages: [
    { role: "system", content: systemPrompt },
    { role: "user", content: userPrompt }
  ]
};

// ===== RETURN CONTEXT WRAPPED =====
return {
  json: {
    context: {
      job,
      job_id: job.job_id ?? null,
      job_url: job.url ?? null,
      source_api: $json.source_api ?? "Unknown",

      job_date_added: date_added.toISOString(),

      job_description_rich_text: chunks,
      job_description_preview: preview,
      job_description_truncated: isTruncated,
      job_description_length: jobDesc.length
    },

    ollama_request_body: ollamaBody
  }
};

const res = $input.first().json;

const jobs = Array.isArray(res.data) ? res.data : [];

return jobs
  .filter(j => j?.job_apply_link) // we dedupe on URL, so require it
  .map(j => ({
    json: {
      source_api: 'JSearch',
      request_id: res.request_id ?? null,
      search_params: res.parameters ?? null, // optional, useful for debugging
      job: {
        url: j.job_apply_link,
        job_id: j.job_id ?? null,
        title: j.job_title ?? null,
        company: j.employer_name ?? null,
        location: j.job_location ?? null,
        city: j.job_city ?? null,
        state: j.job_state ?? null,
        country: j.job_country ?? null,
        posted_at: j.job_posted_at_datetime_utc ?? null,
        //posted_human: j.job_posted_human_readable ?? null,
        employment_type: j.job_employment_type ?? null,
        remote: j.job_is_remote ?? null,
        description: j.job_description ?? null,
      },
    },
  }));

// Mode: Run Once for All Items
return $input.all()
  .filter(item => item.json?.url)
  .map(item => {
    const j = item.json;
    return {
      json: {
        source_api: 'LinkedIn-Search',
        job: {
          url: j.url,
          job_id: j.id ?? j.linkedin_id ?? null,
          title: j.title ?? null,
          company: j.organization ?? null,
          company_url: j.organization_url ?? null,
          location: Array.isArray(j.locations_derived) && j.locations_derived.length
            ? j.locations_derived[0]
            : null,
          posted_at: j.date_posted ?? null,
          description: j.description_text ?? null,
          ats_duplicate: j.ats_duplicate ?? null,
        },
      },
    };
  });

const databaseId = "<NOTION_DATABASE_ID>";

// --------------------------------------------------
// 1️⃣ SAFE STRUCTURED REQUIREMENTS PARSE
// --------------------------------------------------

let structured = {};

if (typeof $json.structured_requirements === "object" && $json.structured_requirements !== null) {
  structured = $json.structured_requirements;
} else if (typeof $json.structured_requirements === "string") {
  try {
    structured = JSON.parse($json.structured_requirements);
  } catch (e) {
    console.error("structured_requirements parse failed:", e.message);
    structured = {};
  }
}

// Ensure shape safety
if (!Array.isArray(structured.must_have)) structured.must_have = [];
if (!Array.isArray(structured.nice_to_have)) structured.nice_to_have = [];
if (!Array.isArray(structured.hard_constraints)) structured.hard_constraints = [];

if (!structured.experience || typeof structured.experience !== "object") {
  structured.experience = {
    min_years: null,
    seniority_level: "unknown"
  };
}

// --------------------------------------------------
// 2️⃣ SAFE CONTEXT RESTORE
// --------------------------------------------------

const context = $json.context ?? {};
const job = context.job ?? {};

const preview = context.job_description_preview ?? "";
const truncated = context.job_description_truncated ?? false;
const length = context.job_description_length ?? null;
const sourceApi = context.source_api ?? "Unknown";
const dateAdded = context.job_date_added ?? null;
const jobId = context.job_id ?? null;

// --------------------------------------------------
// 3️⃣ CHILD BLOCKS (CAP AT 100)
// --------------------------------------------------

const maxBlocks = 100;
const children = (context.job_description_rich_text ?? [])
  .slice(0, maxBlocks)
  .map((chunk) => ({
    object: "block",
    type: "paragraph",
    paragraph: { rich_text: [chunk] },
  }));

// --------------------------------------------------
// 4️⃣ CHUNK STRUCTURED JSON (NO TRUNCATION)
// --------------------------------------------------

const structuredString = JSON.stringify(structured, null, 2);

const maxChunkSize = 1950;
const maxChunks = 100;

const structuredChunks = [];

for (
  let i = 0;
  i < structuredString.length && structuredChunks.length < maxChunks;
  i += maxChunkSize
) {
  structuredChunks.push({
    type: "text",
    text: {
      content: structuredString.slice(i, i + maxChunkSize)
    }
  });
}

// --------------------------------------------------
// 5️⃣ ENRICHMENT FIELDS
// --------------------------------------------------

const minYears = structured.experience.min_years ?? null;
const seniority = structured.experience.seniority_level ?? "unknown";
const cluster = structured.role_cluster_hint ?? null;

// --------------------------------------------------
// 6️⃣ SAFE STRING NORMALIZER
// --------------------------------------------------

const safeText = (val, fallback = "") =>
  typeof val === "string" ? val.slice(0, 2000) : fallback;

// --------------------------------------------------
// 7️⃣ RETURN NOTION PAYLOAD
// --------------------------------------------------
const date = new Date();

return {
  json: {
    parent: { database_id: databaseId },

    properties: {

      Position: {
        rich_text: [{
          text: { content: safeText(job.title, "Untitled") }
        }]
      },

      Company: {
        title: [{
          text: { content: safeText(job.company, "") }
        }]
      },

      Location: {
        rich_text: [{
          text: { content: safeText(job.location, "") }
        }]
      },

      URL: {
        url: job.url || null
      },

      source: {
        select: { name: safeText(sourceApi, "Unknown") }
      },

      date_posted: job.posted_at
        ? { date: { start: job.posted_at } }
        : undefined,

      date_added: dateAdded
        ? { date: { start: dateAdded } }
        : undefined,

      job_description_preview: {
        rich_text: [{
          type: "text",
          text: { content: safeText(preview) }
        }]
      },

      job_description_truncated: {
        checkbox: !!truncated
      },

      job_description_length: {
        number: typeof length === "number" ? length : null
      },

      structured_requirements: {
        rich_text: structuredChunks
      },

      job_minimum_years: {
        number: minYears
      },

      job_cluster: cluster
        ? { select: { name: cluster } }
        : undefined,

      job_seniority: {
        rich_text: [{
          type: "text",
          text: { content: seniority }
        }]
      },

      extractor_version: {
        rich_text: [{
          type: "text",
          text: { content: "Finder.V.0.2" }
        }]
      },
      extractor_run_time:{
        date: {
          start: date.toISOString()
          }
      },
      slug: {
        rich_text: [{
          type: "text",
          text: { content: safeText(jobId ?? "") }
        }]
      }

    },

    children
  }
};

return $input.all().map(item => {

  // ===== Parse Extractor Output Safely =====
  let req = {};

  try {
    req = JSON.parse(item.json.message?.content || "{}");
  } catch (e) {
    req = {};
  }

  if (typeof req !== "object" || req === null) {
    req = {};
  }

  // ===== 1️⃣ Cluster Whitelist =====
  const allowedClusters = ["soc","cloud","grc","appsec","privacy","offensive","general"];

  if (!allowedClusters.includes(req.role_cluster_hint)) {
    req.role_cluster_hint = "general";
  }

  // ===== 2️⃣ Deterministic Seniority Override =====
  const minYears = req.experience?.min_years ?? null;

  if (typeof minYears === "number") {
    if (!req.experience) req.experience = {};
    if (minYears >= 5) {
      req.experience.seniority_level = "senior";
    } else if (minYears >= 3) {
      req.experience.seniority_level = "mid";
    } else {
      req.experience.seniority_level = "junior";
    }
  }

  // ===== 3️⃣ Remove Soft Skills =====
  req.must_have = (req.must_have || []).filter(item =>
    !/communication|analytical ability|attention to detail|interpersonal/i.test(item)
  );

  req.nice_to_have = (req.nice_to_have || []).filter(item =>
    !/communication|interpersonal/i.test(item)
  );

  req.hard_constraints = (req.hard_constraints || []).filter(item =>
    /shift|clearance|citizenship|work authorization|required to work/i.test(item)
  );

  // ===== 6️⃣ Deduplicate Lists =====
  const dedupe = arr => [...new Set(arr)];

  req.must_have = dedupe(req.must_have).slice(0, 6);
  req.nice_to_have = dedupe(req.nice_to_have).slice(0, 4);
  req.hard_constraints = dedupe(req.hard_constraints);

  // ===== 8️⃣ Ensure Arrays Exist =====
  if (!Array.isArray(req.must_have)) req.must_have = [];
  if (!Array.isArray(req.nice_to_have)) req.nice_to_have = [];
  if (!Array.isArray(req.hard_constraints)) req.hard_constraints = [];

  return {
    json: {
      ...item.json,
      structured_requirements: req
    }
  };

});

// ===== FAIL-SAFE JD CLEANER (Improved) =====

return items.map(item => {

  let original = item.json.job?.description || "";
  let description = original;

  let cleaning_confidence = "high";
  let start_anchor_used = null;
  let end_anchor_used = null;

  // -----------------------------
  // PHASE 1: NORMALIZATION
  // -----------------------------

  description = description
    .replace(/\r\n/g, "\n")
    .replace(/\t/g, " ")
    .replace(/ +/g, " ")
    .replace(/\n{3,}/g, "\n\n")
    .trim();

  // remove urls
  description = description.replace(/https?:\/\/\S+/g, "");

  // safer mid-line join
  description = description.replace(/([a-z])\n([A-Z])/g, "$1 $2");

  const lower = description.toLowerCase();

  // -----------------------------
  // PHASE 2: START ANCHOR
  // -----------------------------

  const startAnchors = [

    "responsibilities",
    "key responsibilities",
    "key accountabilities",

    "requirements",
    "qualifications",
    "skills and experience",
    "what you'll need",
    "what you will need",
    "what we are looking for",

    "about the role",
    "role summary"

  ];

  let startIndex = -1;

  const searchLimit = Math.floor(description.length * 0.35);

  for (const marker of startAnchors) {

    const idx = lower.indexOf(marker);

    if (idx !== -1 && idx < searchLimit) {

      startIndex = idx;
      start_anchor_used = marker;
      break;

    }

  }

  let sliced = description;

  if (startIndex !== -1) {
    sliced = description.slice(startIndex);
  } else {
    cleaning_confidence = "low";
  }

  // -----------------------------
  // PHASE 3: END ANCHOR
  // -----------------------------

  const endAnchors = [

    "about us",
    "company overview",
    "equal opportunity employer",
    "diversity and inclusion",
    "benefits",
    "privacy policy",
    "legal disclaimer",
    "job posting end date"

  ];

  const slicedLower = sliced.toLowerCase();

  let endIndex = -1;

  for (const marker of endAnchors) {

    const idx = slicedLower.indexOf(marker);

    if (idx !== -1 && idx > 600) {

      endIndex = idx;
      end_anchor_used = marker;
      break;

    }

  }

  if (endIndex !== -1) {
    sliced = sliced.slice(0, endIndex);
  }

  // -----------------------------
  // PHASE 4: VALIDATION
  // -----------------------------

  if (sliced.length < 400) {

    sliced = original;
    cleaning_confidence = "fallback_length";

  }

  const bulletPattern = /[-–—•*●○]\s|\d+\.\s|\d+\)/;

  const hasBullet = bulletPattern.test(sliced);

  const hasSentence =
    sliced
      .split(".")
      .some(s => s.trim().length > 20);

  if (!hasBullet || !hasSentence) {

    sliced = original;
    cleaning_confidence = "fallback_structure";

  }

  // -----------------------------
  // OUTPUT
  // -----------------------------

  return {

    json: {

      ...item.json,

      job: {
        ...item.json.job,
        description: sliced
      },

      cleaning_meta: {

        start_anchor_used,
        end_anchor_used,

        original_length: original.length,
        cleaned_length: sliced.length,

        cleaning_ratio:
          original.length
            ? (sliced.length / original.length).toFixed(2)
            : null,

        confidence: cleaning_confidence

      }

    }

  };

});

const res = $input.first().json;

const jobs = Array.isArray(res.data) ? res.data : [];

return jobs
  .filter(j => j?.job_apply_link) // we dedupe on URL, so require it
  .map(j => ({
    json: {
      source_api: 'JSearch1',
      request_id: res.request_id ?? null,
      search_params: res.parameters ?? null, // optional, useful for debugging
      job: {
        url: j.job_apply_link,
        job_id: j.job_id ?? null,
        title: j.job_title ?? null,
        company: j.employer_name ?? null,
        location: j.job_location ?? null,
        city: j.job_city ?? null,
        state: j.job_state ?? null,
        country: j.job_country ?? null,
        posted_at: j.job_posted_at_datetime_utc ?? null,
        //posted_human: j.job_posted_human_readable ?? null,
        employment_type: j.job_employment_type ?? null,
        remote: j.job_is_remote ?? null,
        description: j.job_description ?? null,
      },
    },
  }));

// ----------------------------
// Node6: Prepare Jobs For Fit Engine
// ----------------------------

const jobs = $input.all().map(item => {
  const page = item.json;

  const postedDate = page.property_date_posted?.start ?? null;
  const preview = page.property_job_description_preview ?? '';
  const isTruncated = page.property_job_description_truncated === true;

  let structured = {};
  let structuredValid = false;

  const raw = page.property_structured_requirements;

  // ----------------------------
  // Case 1 — Already Object
  // ----------------------------
  if (typeof raw === "object" && raw !== null && !Array.isArray(raw)) {
    structured = raw;
  }

  // ----------------------------
  // Case 2 — Plain JSON String
  // ----------------------------
  else if (typeof raw === "string" && raw.trim().length > 0) {
    try {
      structured = JSON.parse(raw.trim());
    } catch (e) {
      console.error("Structured JSON parse failed (string):", {
        job_page_id: page.id,
        error: e.message
      });
      structured = {};
    }
  }

  // ----------------------------
  // Case 3 — Rich Text Array
  // ----------------------------
  else if (raw?.rich_text && Array.isArray(raw.rich_text)) {
    const fullString = raw.rich_text
      .map(r => r?.text?.content || "")
      .join("");

    if (fullString.trim().length > 0) {
      try {
        structured = JSON.parse(fullString.trim());
      } catch (e) {
        console.error("Structured JSON parse failed (rich_text):", {
          job_page_id: page.id,
          error: e.message
        });
        structured = {};
      }
    }
  }

  // ----------------------------
  // Normalize Structure
  // ----------------------------
  structured.must_have = Array.isArray(structured.must_have)
    ? structured.must_have
    : [];

  structured.nice_to_have = Array.isArray(structured.nice_to_have)
    ? structured.nice_to_have
    : [];

  structured.hard_constraints = Array.isArray(structured.hard_constraints)
    ? structured.hard_constraints
    : [];

  structured.experience =
    structured.experience && typeof structured.experience === "object"
      ? structured.experience
      : { min_years: null, seniority_level: "unknown" };

  structured.role_cluster_hint =
    structured.role_cluster_hint ?? page.property_job_cluster ?? "general";

  structured.role_title =
    structured.role_title ?? page.property_position ?? "";

  // ----------------------------
  // JSON Integrity Check
  // ----------------------------
  if (
    typeof structured === "object" &&
    structured.must_have &&
    structured.nice_to_have &&
    structured.hard_constraints &&
    structured.experience
  ) {
    structuredValid = true;
  }

  return {
    json: {
      job_page_id: page.id,
      job_url: page.property_url ?? '',
      job_title: page.property_position ?? '',
      company: page.property_company ?? '',
      location: page.property_location ?? '',
      posted_date: postedDate,
      description_preview: preview,
      description_truncated: isTruncated,
      structured_requirements: structured,
      structured_valid: structuredValid,
      job_minimum_years: page.property_job_minimum_years ?? null,
      job_seniority: page.property_job_seniority ?? null,
      job_cluster: page.property_job_cluster ?? null,
      job_slug: page.property_slug ?? ''
    }
  };
});

return jobs;

// Mode: Run Once for All Items
return $input.all()
  .filter(item => item.json?.url)
  .map(item => {
    const j = item.json;
    return {
      json: {
        source_api: 'LinkedIn-Search',
        job: {
          url: j.url,
          job_id: j.id ?? j.linkedin_id ?? null,
          title: j.title ?? null,
          company: j.organization ?? null,
          company_url: j.organization_url ?? null,
          location: Array.isArray(j.locations_derived) && j.locations_derived.length
            ? j.locations_derived[0]
            : null,
          posted_at: j.date_posted ?? null,
          description: j.description_text ?? null,
          ats_duplicate: j.ats_duplicate ?? null,
        },
      },
    };
  });
